-- Transactional acceptance, authorization and synchronization checks.
-- Every synthetic account, request, notification and push queue entry rolls back.
begin;
create temporary table ext_test_ctx(office_id uuid,viewer_id uuid,first_id uuid,second_id uuid,installer_id uuid,other_installer_id uuid,request_id uuid,counter_id uuid,overlap_id uuid);
insert into ext_test_ctx(office_id,viewer_id,first_id,second_id) select id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid() from public.profiles where role='office_scheduler' and active limit 1;
do $$declare c ext_test_ctx;uid uuid;begin
 select * into c from ext_test_ctx;
 foreach uid in array array[c.viewer_id,c.first_id,c.second_id] loop
  insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role) values(uid,'pwqa-'||uid||'@example.invalid',jsonb_build_object('full_name','PW QA '||uid),'{}','authenticated','authenticated');
 end loop;
 update public.profiles set role='office_viewer' where id=c.viewer_id;
 update ext_test_ctx set installer_id=public.pw_external_provision(c.first_id,'PW QA first','PW QA company','pwqa-first@example.invalid','',''),other_installer_id=public.pw_external_provision(c.second_id,'PW QA second','PW QA company 2','pwqa-second@example.invalid','','');
end;$$;
grant select,update on ext_test_ctx to authenticated;
set local role authenticated;
do $$declare c ext_test_ctx;r public.external_requests;r2 public.external_requests;rep public.external_reports;t public.external_tests;payload jsonb;denied boolean;current_day date:=(now() at time zone 'Europe/Rome')::date;begin
 select * into c from ext_test_ctx;
 perform set_config('request.jwt.claim.sub',c.office_id::text,true);
 payload:=jsonb_build_object('installer_id',c.installer_id,'address','Via di prova 1','floor','1','description','Posa serramenti di prova','price',1500,'work_dates',jsonb_build_array(current_day),'start_time','08:00','end_time','17:00');
 r:=public.pw_external_save_request(payload,null,null);
 update ext_test_ctx set request_id=r.id;
 if r.status<>'pending' or r.linked_pose_id is not null then raise exception 'TEST failed: pending request created a confirmed pose';end if;
 perform set_config('request.jwt.claim.sub',c.second_id::text,true);
 if exists(select 1 from public.external_requests where id=r.id) then raise exception 'TEST failed: external installer sees another installer request';end if;
 denied:=false;begin perform public.pw_external_respond(r.id,'accept',r.version,'{"accept_conditions":true}');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: another installer accepted the request';end if;
 perform set_config('request.jwt.claim.sub',c.first_id::text,true);
 denied:=false;begin perform public.pw_external_respond(r.id,'accept',r.version,'{}');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: conditions not enforced';end if;
 r:=public.pw_external_respond(r.id,'accept',r.version,'{"accept_conditions":true}');
 if r.status<>'confirmed' or r.linked_pose_id is null then raise exception 'TEST failed: acceptance did not synchronize';end if;
 if not exists(select 1 from public.poses where id=r.linked_pose_id and external_request_id=r.id) then raise exception 'TEST failed: linked pose missing';end if;
 if (select count(*) from public.external_bookings where request_id=r.id)<>1 or (select count(*) from public.pose_dates where pose_id=r.linked_pose_id)<>1 then raise exception 'TEST failed: dates not locked exactly once';end if;
 denied:=false;begin perform public.pw_external_respond(r.id,'accept',r.version-1,'{"accept_conditions":true}');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: stale duplicate acceptance allowed';end if;
 denied:=false;begin perform public.pw_external_save_report(r.id,r.version,jsonb_build_object('report_date',current_day,'description','Lavoro parziale','incomplete',true,'reason',''));exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: missing incomplete reason accepted';end if;
 denied:=false;begin perform public.pw_external_save_report(r.id,r.version,jsonb_build_object('report_date',current_day+1,'description','Rapporto futuro'));exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: future report accepted';end if;
 rep:=public.pw_external_save_report(r.id,r.version,jsonb_build_object('report_date',current_day,'description','Lavoro parziale','incomplete',true,'reason','Manca un componente'));
 select * into r from public.external_requests where id=r.id;
 if r.status<>'incomplete' then raise exception 'TEST failed: incomplete status not set';end if;
 denied:=false;begin perform public.pw_external_save_test(r.id,r.version,jsonb_build_object('test_date',current_day,'outcome','conforme','checks','Verifica di prova','cleaned',true,'operator_name','Posatore QA'));exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: incomplete work passed final test';end if;
 rep:=public.pw_external_save_report(r.id,r.version,jsonb_build_object('report_date',current_day,'description','Lavoro terminato','incomplete',false,'reason',''));
 select * into r from public.external_requests where id=r.id;
 denied:=false;begin perform public.pw_external_save_test(r.id,r.version,jsonb_build_object('test_date',current_day,'outcome','conforme','checks','Verificato','cleaned',false,'operator_name','QA'));exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: cleaning not enforced at conclusion';end if;
 t:=public.pw_external_save_test(r.id,r.version,jsonb_build_object('test_date',current_day,'outcome','conforme','checks','Verificato','cleaned',true,'operator_name','QA'));
 select * into r from public.external_requests where id=r.id;
 if r.status<>'completed' then raise exception 'TEST failed: final test did not conclude work';end if;
 perform set_config('request.jwt.claim.sub',c.office_id::text,true);
 denied:=false;begin update public.poses set address='Not allowed' where id=r.linked_pose_id;exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: legacy app can desynchronize external pose';end if;
 r2:=public.pw_external_save_request(payload,null,null);update ext_test_ctx set overlap_id=r2.id;
 perform set_config('request.jwt.claim.sub',c.first_id::text,true);
 denied:=false;begin perform public.pw_external_respond(r2.id,'accept',r2.version,'{"accept_conditions":true}');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: overlapping confirmed dates allowed';end if;
 select * into r2 from public.external_requests where id=r2.id;if r2.status<>'pending' or r2.linked_pose_id is not null then raise exception 'TEST failed: conflict did not roll back atomically';end if;
 perform set_config('request.jwt.claim.sub',c.office_id::text,true);
 payload:=jsonb_set(payload,'{work_dates}',jsonb_build_array(current_day+1));r2:=public.pw_external_save_request(payload,null,null);update ext_test_ctx set counter_id=r2.id;
 perform set_config('request.jwt.claim.sub',c.first_id::text,true);
 r2:=public.pw_external_respond(r2.id,'propose',r2.version,jsonb_build_object('dates',jsonb_build_array(current_day+2),'accept_conditions',true,'note','Data alternativa'));
 if r2.linked_pose_id is not null then raise exception 'TEST failed: counterproposal blocked dates before office acceptance';end if;
 denied:=false;begin perform public.pw_external_respond(r2.id,'approve_dates',r2.version,'{}');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: installer approved own counterproposal';end if;
 perform set_config('request.jwt.claim.sub',c.office_id::text,true);
 r2:=public.pw_external_respond(r2.id,'reject_dates',r2.version,'{}');
 perform set_config('request.jwt.claim.sub',c.first_id::text,true);
 r2:=public.pw_external_respond(r2.id,'propose',r2.version,jsonb_build_object('dates',jsonb_build_array(current_day+2),'accept_conditions',true));
 perform set_config('request.jwt.claim.sub',c.office_id::text,true);
 r2:=public.pw_external_respond(r2.id,'approve_dates',r2.version,'{}');
 if r2.status<>'confirmed' or r2.work_dates<>array[current_day+2] or r2.linked_pose_id is null then raise exception 'TEST failed: approved counterproposal did not synchronize';end if;
 payload:=jsonb_set(payload,'{work_dates}',jsonb_build_array(current_day+3));r2:=public.pw_external_save_request(payload,null,null);
 perform set_config('request.jwt.claim.sub',c.first_id::text,true);
 r2:=public.pw_external_respond(r2.id,'reject',r2.version,'{"note":"Non disponibile"}');
 if r2.status<>'rejected' or r2.linked_pose_id is not null then raise exception 'TEST failed: full rejection created pose';end if;
 perform set_config('request.jwt.claim.sub',c.viewer_id::text,true);
 denied:=false;begin perform public.pw_external_save_request(payload,null,null);exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: office viewer wrote a request';end if;
 denied:=false;begin perform public.pw_external_register_file(r.id,'before','requests/'||r.id||'/before/'||c.viewer_id||'/photo.jpg','photo.jpg');exception when others then denied:=true;end;if not denied then raise exception 'TEST failed: office viewer uploaded';end if;
 if has_table_privilege('authenticated','public.external_requests','insert') or has_function_privilege('anon','public.pw_external_respond(uuid,text,integer,jsonb)','execute') or has_function_privilege('authenticated','public.pw_external_provision(uuid,text,text,text,text,text)','execute') then raise exception 'TEST failed: privileged mutation exposed';end if;
end;$$;
reset role;
do $$begin
 if exists(select 1 from public.notifications n join public.external_events e on e.request_id=n.entity_id and e.action=n.event_action join public.profiles p on p.id=e.actor_id where n.actor_name=p.full_name and n.recipient_id=e.actor_id and e.request_id in(select id from public.external_requests where created_by=(select office_id from ext_test_ctx))) then raise exception 'TEST failed: action sent notification to its author';end if;
 if exists(select 1 from public.notifications n join public.poses p on p.id=n.pose_id where p.external_request_id in(select id from public.external_requests where created_by=(select office_id from ext_test_ctx)) and n.notification_type not like 'external_%') then raise exception 'TEST failed: duplicate legacy notifications for external pose';end if;
end;$$;
rollback;
select 'PASS: isolation, roles, conditions, acceptance, duplicate protection, day locking, overlap rollback, daily reports, incomplete reasons, final test, counterproposal approval/refusal, full rejection, reciprocal notifications and legacy preservation' as result;
